 function weekdays(){return Array.from({length:7},(_,i)=>{const day=(firstDay()+i)%7;return {day,label:date('2024-01-'+String(7+day).padStart(2,'0'),{weekday:'short',month:undefined,day:undefined})}})}
 function distance(meters){const imperial=config.units==='imperial'||config.units==='auto'&&['US','LR','MM'].includes(region());return number(meters/(imperial?1609.344:1000),{style:'unit',unit:imperial?'mile':'kilometer',unitDisplay:'short',maximumFractionDigits:1})}
