  assert(typeof s.calendar.viewOrder === 'string' && s.calendar.viewOrder === calendarViewOrder(s).join(',') && ['month','week','day'].includes(s.calendar.todayView), HML.t("캘린더 보기 순서를 확인해 주세요."));
