  if(!/^[a-z]{2,3}(?:-[A-Za-z0-9]{2,8}){0,3}$/.test(l.resolvedLanguage||''))l.resolvedLanguage='en-US';
  assert(l.language==='auto'||/^[a-z]{2,3}(?:-[A-Za-z0-9]{2,8}){0,3}$/.test(l.language),HML.t("지원하는 언어를 선택해 주세요."));
  assert(l.region==='auto'||/^[A-Z]{2}$/.test(l.region),HML.t("지역을 선택해 주세요."));
  assert(['auto','h12','h23'].includes(l.hourCycle)&&['auto','0','1','6'].includes(String(l.weekStart))&&['auto','latn'].includes(l.numbering)&&['auto','metric','imperial'].includes(l.units),HML.t("언어와 지역 설정을 확인해 주세요."));
  l.weekStart=String(l.weekStart);l.updatedAt=number(l.updatedAt,0,Number.MAX_SAFE_INTEGER,HML.t("언어 설정 시각"));
  for(const [group,keys] of Object.entries({notifications:['enabled','escalate','includeTasks','includeEvents','includeTravel','lockscreenDetails'],sleep:['enabled','systemDnd','usageWarning'],google:['calendarEnabled','driveEnabled','autoSync'],feedback:['sound','haptic'],planning:['respectDeadline']})) for(const k of keys) assert(typeof s[group][k]==='boolean', HML.t("설정 형식을 확인해 주세요."));
