  for(const k of ['intervalMinutes','vibrateAfterMinutes','soundAfterMinutes']) s.notifications[k] = number(s.notifications[k],1,1440,HML.t("알림 간격"));
  assert(s.notifications.soundAfterMinutes>s.notifications.vibrateAfterMinutes,HML.t("소리 강화 시각은 진동 강화 이후여야 해요."));
