function canReadOwner(actor, owner) { return !!actor && !!owner && !!actor.family_id && actor.family_id === owner.family_id && ['parent','child'].includes(actor.role) && ['parent','child'].includes(owner.role) && (actor.id === owner.id || (actor.role === 'parent' && owner.role === 'child')); }
