          credit(actor.id, (next ? 1 : -1) * row.award_points, next ? HML.t("할 일 완료") : HML.t("할 일 완료 취소"));
          if (row.goal_id) goalAdjust(owned('goals', row.goal_id), (next ? 1 : -1) * Number(row.goal_amount));
          if (next) row.checklist = row.checklist.map(c => ({ ...c, done: true }));
