   if(panel&&!panel.querySelector('.gs-family-progress'))panel.insertAdjacentHTML('afterbegin',familyProgress(A.gateway));
   if(pendingInvitation){try{const inv=HMSheetsCore.validateInvitation(pendingInvitation);if(A.gateway.own.connections?.some(c=>c.direction==='inbound'&&c.fileId===inv.fileId)){pendingInvitation='';if(A.gateway.own.members.find(m=>m.id===A.gateway.user.id)?.role==='child')queueMicrotask(()=>family('send'));}}catch{pendingInvitation='';}}
