 function readOnly(container,row){if(container.querySelector('.hm-read-extras'))return;const el=document.createElement('section');el.className='hm-read-extras';el._row=row;const dep=E.departureFor(row,zone());el.innerHTML=HML.html`<div class="hm-files">${(row.attachments||[]).map(x=>card(x)).join('')}</div>${row.location?HML.html`<div class="hm-location-card"><strong>${h(row.location.name||HML.t("장소"))}</strong><small>${h(row.location.address)}</small><a href="https://www.google.com/maps/dir/?api=1&destination=${row.location.lat},${row.location.lng}" target="_blank" rel="noopener noreferrer">길찾기 열기</a>${dep?HML.html`<p>출발 ${h(HML.time(E.parts(dep.at,zone()).time))} · ${Math.ceil(dep.minutes)}분 이동${dep.stale?HML.t(" · 이동 시간을 다시 확인해 주세요"):''}</p>`:''}</div>`:''}${row.deadline_at?HML.html`<p class="muted">원래 마감 ${h(HML.timestamp(row.deadline_at,zone()))}</p>`:''}`;container.append(el);tilePreviews(el.querySelector('.hm-files'),container,row.owner_id)(row.attachments||[]);}
