async function boot() {
  try {
    if (config.mode === 'demo') gateway = new DemoGateway();
    else if (config.mode === 'sheets') gateway = new HMGoogleGateway(config);
    else if (config.mode === 'cloud') gateway = new CloudGateway(config);
    else throw new Error(HML.t("실행 모드를 확인해 주세요. config.js의 mode는 demo 또는 cloud입니다."));
    s.signedIn = await gateway.init();
    if (gateway.recovery) s.authMode = 'change';
    if (s.signedIn) { await refresh(); if (s.data?.family) { s.date = today(s.data.family.timezone); render(); } }
    else render();
    setInterval(() => { if (s.signedIn && !document.hidden && !s.busy && !refreshPromise) refresh().catch(() => {}); }, Math.max(30000, Number(config.pollMs) || 60000));
    if (location.protocol !== 'file:' && 'serviceWorker' in navigator && window.HARUMOA_BUILT) navigator.serviceWorker.register('./sw.js').catch(() => {});
  } catch (error) {
    s.error = friendlyError(error);
    if (gateway?.mode === 'cloud' && gateway.session) s.signedIn = true;
    if (s.signedIn) render();
    else if (gateway) { s.authMessage = s.error; render(); }
    else root.innerHTML = HML.html`<main class="onboarding"><section class="panel"><h1>연결 설정이 필요해요</h1><p>${e(s.error)}</p><p>실제 서버 주소와 공개용 키를 설정한 뒤 다시 실행해 주세요. 클라우드 설정 오류를 체험 모드로 바꾸어 숨기지 않습니다.</p></section></main>`;
  }
}
function calendarRouteMode(view, entryContext) {
  if (view !== 'calendar') return s.calendarMode;
  return ['month','week','day'].includes(entryContext?.calendarMode) ? entryContext.calendarMode : HMEngine.calendarViewOrder(s.data?.preferences)[0];
}
navigation = new PageNavigator({
  root,
  routes: NAV,
  state: () => s,
  onMenuTap: () => Feedback.tap(),
  // Navigation clears the Today filters. Its inert preview must use the same
  // state as commit, otherwise rows change height as the overlay is removed.
  preview: (view, entryContext) => appView({ ...s, view, calendarMode: calendarRouteMode(view, entryContext), owner: s.data.profile.id, date: s.view === 'family' && view !== 'family' ? (s.personalDate || today(s.data.family.timezone)) : s.date, search: '', category: '', taskFilter: 'all' }),
  commit: (view, scroll, preparedTemplate, entryContext) => {
    s.calendarMode = calendarRouteMode(view, entryContext);
    if (view === 'family' && s.view !== 'family') s.personalDate = s.date;
    if (s.view === 'family' && view !== 'family') { s.date = s.personalDate || today(s.data.family.timezone); s.familyOwner = ''; s.familyTab = 'today'; }
    s.owner = s.data.profile.id; s.view = view; s.search = ''; s.category = ''; s.taskFilter = 'all';
    render({ horizontal: true, preparedTemplate }); window.scrollTo({ top: scroll, behavior: 'instant' });
  }
});
installPressMotion();
Feedback.install();
composer = new ActivityComposer({
  state: () => s,
  notify: toast,
  launch: options => creation.open(options),
  onOpen: () => creation.mount(composer.dialog, 'activity'),
  onClose: options => creation.closed(composer.dialog, options),
  save: async (payload, errorTarget) => {
    const result = await mutate('activity_save', payload, payload.kind === 'event' ? HML.t("일정을 추가했어요.") : HML.t("할 일을 추가했어요."), { close: false, errorTarget });
    if (result?.ok && s.owner !== s.data.profile.id) {
      s.owner = s.data.profile.id; s.view = 'today'; s.search = ''; s.category = ''; s.taskFilter = 'all';
      await goDate(payload.due_date);
    }
    return result;
  }
});
creation = new CreationPicker();
const hmAPI={state:s,get gateway(){return gateway;},get composer(){return composer;},Feedback,showDialog,modalForm,closeDialog,toast,render,refresh,mutate,legacySettings:settingsModal,
 makeCloud(){const g=gateway?.kind==='sheets'?gateway:config.mode==='sheets'?new HMGoogleGateway(config):gateway?.mode==='cloud'?gateway:new CloudGateway(config);return g;},
 useCloud(g){gateway=g;s.mode='cloud';s.signedIn=!!g.session;resetAccountView();},
 async enterDemo(){if(s.signedIn)throw new Error(HML.t("로그아웃 후 체험 계정을 선택해 주세요."));gateway=new DemoGateway();s.mode='demo';await gateway.signInPreview(gateway.state.members.find(m=>m.role==='parent').id);resetAccountView();s.signedIn=true;await refresh();},
};
