HM7.bind(hmAPI,__modules); HML.bind(hmAPI); HMGoogleUI.bind(hmAPI);
boot();

// Android shell calls this fixed handler. IME/back handling otherwise stays native.
window.harumoaBack = () => {
  const extra = [...document.querySelectorAll('dialog.hm-dialog[open]')].pop(); if (extra) { extra.close(); return true; }
  if (composer?.dialog.open) { composer.close(); return true; }
  if (dialog.open) { closeDialog(); return true; }
  if (!s.signedIn && s.authMode !== 'signin') { s.authMode = 'signin'; s.authMessage = ''; render(); return true; }
  if (s.view === 'family' && s.familyOwner) { s.familyOwner = ''; s.familyTab = 'today'; render(); return true; }
  if (s.view !== 'today') { navigation.go('today'); return true; }
  return false;
};

